import {fallsFromAbove,overheadDelivery} from './delivery.mjs?v=growthfall1';
export function forceSpec(seq){if(!'wg'.includes(seq[0]))return null;const n=seq.length;return {kind:seq[0],rings:n,height:2.5+n*.9,radius:.38+(n-1)*.25,falling:fallsFromAbove(seq),overhead:overheadDelivery(seq),range:3+(n-1)*1.5,force:(seq[0]==='g'?-1:1)*(1.2+(n-1)*.9),halfAngle:.6+(n-1)*.08,speed:10,damage:3+n,slow:seq.includes('i')?1.5:0,burn:seq.includes('q')?2:0,echo:0,shield:seq.includes('e')?12:0};}
export function wardSpec(seq){return {range:6,hp:24+(seq.length-1)*24,duration:3+(seq.length-1)*2,width:2.6+(seq.length-1)*.4,burn:seq.includes("q")?2:0,slow:seq.includes("i")?1.5:0,shock:seq.includes("l")?5:0,push:seq.includes("w")?1.4:0,pull:seq.includes("g")?.8:0,colors:[...new Set(seq.slice(1))]};}
export function displacement(force,distance){return force<0?-(Math.min(-force,Math.max(0,distance-.9)))||0:force;}
// Swept segment vs finite wall, expanded by the projectile radius.
export function crossesWard(from,to,wall,radius=.2){const ax=from.x-wall.x,az=from.z-wall.z,bx=to.x-wall.x,bz=to.z-wall.z,a=ax*wall.nx+az*wall.nz,b=bx*wall.nx+bz*wall.nz;if(a*b>0&&Math.min(Math.abs(a),Math.abs(b))>radius)return false;const t=Math.abs(a-b)<1e-8?0:Math.max(0,Math.min(1,a/(a-b))),x=ax+(bx-ax)*t,z=az+(bz-az)*t;return Math.abs(-wall.nz*x+wall.nx*z)<=wall.width/2+radius;}
export function forceDescription(seq){if(seq[0]==='e'){const s=wardSpec(seq);return `조준한 곳에 장막을 세웁니다. 설치 거리 최대 ${s.range}m · 내구도 ${s.hp} · ${s.duration}초 유지. 양쪽 캐릭터의 이동과 적의 투사체를 막고, 내구도가 소진되면 사라집니다. 바닥 범위 공격은 막지 않습니다. 다시 설치하면 이전 장막을 교체합니다.${s.burn?" 가까운 적에게 화상을 남깁니다.":""}${s.slow?" 가까운 적을 느리게 합니다.":""}${s.shock?" 가까운 적에게 주기적으로 벼락을 떨어뜨립니다.":""}${s.push?" 가까운 적을 벽에서 밀어냅니다.":""}${s.pull?" 가까운 적을 벽으로 끌어옵니다.":""}`;}const s=forceSpec(seq);if(!s)return null;let text=`전방 ${s.range}m에 충격파를 보내 적을 최대 ${Math.abs(s.force).toFixed(1)}m ${s.force<0?'끌어당깁니다':'밀어냅니다'}. 벽을 넘거나 시전자를 지나치지 않습니다.`;if(s.falling)text=`${s.range}m 안의 대상 머리 위에서 ${seq[0]==='w'?'연두색 밀기':'보라색 당김'} 충격파가 떨어집니다. 0.28초 뒤 작은 원 안을 타격하고 적을 시전자 기준으로 최대 ${Math.abs(s.force).toFixed(1)}m ${s.force<0?'끌어당깁니다':'밀어냅니다'}. 범위를 벗어나거나 구르면 피할 수 있습니다. 대상이 없으면 사거리 안 임의 지점에 떨어집니다.`;if(s.burn)text+=' 화상을 남깁니다.';if(s.slow)text+=' 이동 속도를 낮춥니다.';if(s.echo)text+=' 추가 방전 피해를 줍니다.';if(s.shield)text+=' 자신에게 짧은 보호막을 두릅니다.';return text;}

export function distanceToWard(point,wall){const x=point.x-wall.x,z=point.z-wall.z,normal=x*wall.nx+z*wall.nz,along=-x*wall.nz+z*wall.nx;return Math.hypot(normal,Math.max(0,Math.abs(along)-wall.width/2));}
